```go
func (r *Retrier) Do(ctx context.Context, operation func(ctx context.Context) error) error {
    var lastErr error
    for attempt := 0; attempt < r.config.MaxAttempts; attempt++ {
        err := operation(ctx)
        if err == nil {
            return nil
